function isPrime(num) {
  if (num <= 1) return false;
  if (num <= 3) return true;
  if (num % 2 === 0 || num % 3 === 0) return false;

  for (let i = 5; i * i <= num; i += 6) {
    if (num % i === 0 || num % (i + 2) === 0) return false;
  }
  return true;
}

function processNumbers(numbers) {
  const results = [];
  for (let i = 0; i < numbers.length; i += 1) {
    if (numbers[i] > 1) { 
      let isNumPrime = true;
      if (numbers[i] <= 3) {
        isNumPrime = true;
      } else if (numbers[i] % 2 === 0 || numbers[i] % 3 === 0) {
        isNumPrime = false;
      } else {
        for (let j = 5; j * j <= numbers[i]; j += 6) {
          if (numbers[i] % j === 0 || numbers[i] % (j + 2) === 0) {
            isNumPrime = false;
            break;
          }
        }
      }
      results.push({ number: numbers[i], isPrime: isNumPrime });
    } else {
      results.push({ number: numbers[i], isPrime: false });
    }
  }
  return results;
}

const testNumbers = [17, 20, 257, 1024, 65537, 4096];
const processedResults = processNumbers(testNumbers);
// console.log(processedResults);

function getPrimesUpTo(limit) {
  if (limit < 2) return [];
  const sieve = new Array(limit + 1).fill(true);
  sieve[0] = false;
  sieve[1] = false;

  for (let p = 2; p * p <= limit; p += 1) {
    if (sieve[p]) {
      for (let i = p * p; i <= limit; i += p) {
        sieve[i] = false;
      }
    }
  }

  const primes = [];
  for (let i = 2; i <= limit; i += 1) {
    if (sieve[i]) {
      primes.push(i);
    }
  }
  return primes;
}

