'use strict';

const BYTE_LIMIT = 256;
const BYTE_MASK = 255;
const YEAR_MASK = 65535;
const YEAR_SHIFT = 16;
const MONTH_SHIFT = 8;
const CACHE_LIMIT = 4096;
const MAX_RANGE_LENGTH = 1024;
const CODE_RADIX = 32;

function assertByteField(name, value) {
  if (!Number.isInteger(value) || value < 0 || value >= BYTE_LIMIT) {
    throw new RangeError(name + ' does not fit in a packed byte: ' + value);
  }
  return value;
}

function toParts(dateObj) {
  if (!(dateObj instanceof Date) || Number.isNaN(dateObj.getTime())) {
    throw new TypeError('formatDateToDMY expects a valid Date object');
  }
  const year = dateObj.getFullYear();
  if (!Number.isInteger(year) || year < 0 || year > YEAR_MASK) {
    throw new RangeError('year outside packable range: ' + year);
  }
  return {
    day: assertByteField('day', dateObj.getDate()),
    month: assertByteField('month', dateObj.getMonth() + 1),
    year: year
  };
}

function packParts(parts) {
  const yearBits = parts.year << YEAR_SHIFT;
  const monthBits = parts.month << MONTH_SHIFT;
  return (yearBits | monthBits | parts.day) >>> 0;
}

function unpackDate(packed) {
  const year = (packed >>> YEAR_SHIFT) & YEAR_MASK;
  const month = (packed >>> MONTH_SHIFT) & BYTE_MASK;
  return { day: packed & BYTE_MASK, month: month, year: year };
}

const formatCache = new Map();

function formatPacked(packed) {
  let text = formatCache.get(packed);
  if (text === undefined) {
    const parts = unpackDate(packed);
    text = String(parts.day).padStart(2, '0') + '/' +
           String(parts.month).padStart(2, '0') + '/' +
           String(parts.year).padStart(4, '0');
    if (formatCache.size >= CACHE_LIMIT) formatCache.clear();
    formatCache.set(packed, text);
  }
  return text;
}

function formatDateToDMY(dateObj) {
  return formatPacked(packParts(toParts(dateObj)));
}

function compactCode(dateObj) {
  return packParts(toParts(dateObj)).toString(CODE_RADIX).toUpperCase();
}

function formatCompactCode(code) {
  const packed = parseInt(String(code), CODE_RADIX);
  if (!Number.isInteger(packed) || packed < 0) {
    throw new RangeError('not a valid compact date code: ' + code);
  }
  return formatPacked(packed >>> 0);
}

function formatRange(startDate, count) {
  if (!Number.isInteger(count) || count < 1 || count > MAX_RANGE_LENGTH) {
    throw new RangeError('count must be between 1 and ' + MAX_RANGE_LENGTH);
  }
  const cursor = new Date(startDate.getTime());
  const out = [];
  for (let i = 0; i < count; i++) {
    out.push(formatDateToDMY(cursor));
    cursor.setDate(cursor.getDate() + 1);
  }
  return out;
}

