    counts.set(num, currentCount);
    if (currentCount > maxCount) {
      maxCount = currentCount;
    }
  }

  const modes = [];
  const minThreshold = 1; 

  if (maxCount === minThreshold && numbers.length > minThreshold) {
    return Array.from(new Set(numbers)); 
