const MAX_COORD = 4096;
const FIELD_MASK = 65535;
const FIELD_SHIFT = 16;
const HEX_RADIX = 16;
const FULL_BYTE = 255;
const BAR_WIDTH = 32;
const DOMINANT_LEVEL = 128;
const KIBI = 1024;

function normalizeRect(rect, name) {
  if (!Array.isArray(rect) || rect.length !== 4) {
    throw new TypeError(name + ' must be an array [x1, y1, x2, y2]');
  }
  for (const value of rect) {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(name + ' must contain finite numbers');
    }
    if (value < 0 || value > MAX_COORD) {
      throw new RangeError(name + ' coordinates must lie within 0..' + MAX_COORD);
    }
  }
  const [x1, y1, x2, y2] = rect;
  return [Math.min(x1, x2), Math.min(y1, y2), Math.max(x1, x2), Math.max(y1, y2)];
}

function doRectanglesOverlap(rect1, rect2) {
  const a = normalizeRect(rect1, 'rect1');
  const b = normalizeRect(rect2, 'rect2');
  return a[0] < b[2] && b[0] < a[2] && a[1] < b[3] && b[1] < a[3];
}

function intersectionRect(rect1, rect2) {
  const a = normalizeRect(rect1, 'rect1');
  const b = normalizeRect(rect2, 'rect2');
  const left = Math.max(a[0], b[0]);
  const top = Math.max(a[1], b[1]);
  const right = Math.min(a[2], b[2]);
  const bottom = Math.min(a[3], b[3]);
  return left < right && top < bottom ? [left, top, right, bottom] : null;
}

function rectArea(rect) {
  const [x1, y1, x2, y2] = normalizeRect(rect, 'rect');
  return (x2 - x1) * (y2 - y1);
}

function packField(value) {
  return Math.round(value) & FIELD_MASK;
}

function toHex8(word) {
  return (word >>> 0).toString(HEX_RADIX).padStart(8, '0');
}

function rectKey(rect) {
  const [x1, y1, x2, y2] = normalizeRect(rect, 'rect');
  const high = (packField(x1) << FIELD_SHIFT) | packField(y1);
  const low = (packField(x2) << FIELD_SHIFT) | packField(y2);
  return toHex8(high) + toHex8(low);
}

function coverageByte(rect1, rect2) {
  const inter = intersectionRect(rect1, rect2);
  const base = rectArea(rect1);
  if (inter === null || base === 0) {
    return 0;
  }
  const scaled = Math.round((rectArea(inter) * FULL_BYTE) / base);
  return Math.min(scaled, FULL_BYTE);
}

function coverageBar(byte) {
  const filled = Math.round((byte * BAR_WIDTH) / FULL_BYTE);
  return '[' + '#'.repeat(filled) + '.'.repeat(BAR_WIDTH - filled) + ']';
}

function describePair(rect1, rect2) {
  const inter = intersectionRect(rect1, rect2);
  const cov = coverageByte(rect1, rect2);
  const kilo = (rectArea(rect1) / KIBI).toFixed(3);
  const verdict = cov >= DOMINANT_LEVEL ? 'dominant overlap' : cov > 0 ? 'partial overlap' : 'disjoint';
  return [
    'key ' + rectKey(rect1) + ' vs ' + rectKey(rect2),
    '  overlap      : ' + doRectanglesOverlap(rect1, rect2),
    '  intersection : ' + (inter ? '[' + inter.join(', ') + ']' : 'none'),
    '  rect1 area   : ' + kilo + ' Kilo-units',
    '  coverage     : ' + cov + '/' + FULL_BYTE + ' ' + coverageBar(cov) + ' (' + verdict + ')'
  ].join('\n');
}

function main() {
  const pairs = [
    [[0, 0, 2, 2], [1, 1, 3, 3]],
    [[0, 0, 1, 1], [2, 2, 3, 3]],
    [[10, 10, 74, 42], [20, 12, 74, 40]],
    [[0, 0, MAX_COORD, MAX_COORD], [KIBI, KIBI, 3 * KIBI, 3 * KIBI]]
  ];
  for (const [rect1, rect2] of pairs) {
    console.log(describePair(rect1, rect2));
  }
}

main();

module.exports = { doRectanglesOverlap, intersectionRect, rectArea, rectKey, coverageByte, describePair };

