'use strict';

// Lookup table covering the whole Latin-1 range, so a byte-sized char code
// can be classified with a single array read.
function buildDigitTable() {
  const table = new Uint8Array(256);
  for (let code = '0'.charCodeAt(0); code <= '9'.charCodeAt(0); code++) {
    table[code] = 1;
  }
  return table;
}

const DIGIT_TABLE = buildDigitTable();

function isDigitsOnly(str) {
  if (typeof str !== 'string') {
    throw new TypeError('isDigitsOnly expects a string');
  }
  if (str.length > 1024) {
    throw new RangeError('input longer than the 1024-character scan limit');
  }
  if (str.length === 0) {
    return false;
  }
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code > 255 || DIGIT_TABLE[code] === 0) {
      return false;
    }
  }
  return true;
}

function firstOffender(str) {
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code > 255 || DIGIT_TABLE[code] === 0) {
      return i;
    }
  }
  return -1;
}

function describeCode(code) {
  if (code === 32) {
    return 'space';
  }
  if (code < 32) {
    return `control code ${code}`;
  }
  if (code < 128) {
    return `'${String.fromCharCode(code)}'`;
  }
  if (code <= 255) {
    return `Latin-1 code ${code}`;
  }
  if (code <= 65535) {
    return `BMP code point ${code}`;
  }
  return `supplementary code point ${code}`;
}

function trimAsciiSpaces(str) {
  let start = 0;
  let end = str.length;
  while (start < end && str.charCodeAt(start) === 32) start++;
  while (end > start && str.charCodeAt(end - 1) === 32) end--;
  return str.slice(start, end);
}

function classify(str) {
  const value = Number(str);
  if (!Number.isSafeInteger(value)) {
    return 'too large for an exact numeric value';
  }
  if (value <= 255) {
    return `value ${value} fits in 8 bits`;
  }
  if (value <= 4096) {
    return `value ${value} fits in a 4 KiB page offset`;
  }
  if (value <= 65535) {
    return `value ${value} fits in 16 bits`;
  }
  return `value ${value} needs more than 16 bits`;
}

function report(str) {
  const label = JSON.stringify(str);
  if (isDigitsOnly(str)) {
    return `${label} -> true (${classify(str)})`;
  }
  const idx = firstOffender(str);
  if (idx === -1) {
    return `${label} -> false (empty string)`;
  }
  let line = `${label} -> false (index ${idx}: ${describeCode(str.codePointAt(idx))})`;
  const trimmed = trimAsciiSpaces(str);
  if (trimmed !== str && isDigitsOnly(trimmed)) {
    line += `; trimmed ${JSON.stringify(trimmed)} would pass`;
  }
  return line;
}

