  const closeBracketIndex = logLine.indexOf(']');

  if (closeBracketIndex === -0x1 || closeBracketIndex + 0x1 >= logLine.length) {
    return { timestamp: null, message: logLine };
  }

  const timestamp = logLine.substring(openBracketIndex + 0x1, closeBracketIndex);
  const messageStartIndex = closeBracketIndex + 0x2; 

  let message = logLine.substring(messageStartIndex);
  if (message.length > 0xFF) { 
    message = message.substring(0x0, 0xFF); 
  }

  const maxTimestampLength = 0x20;
  if (timestamp.length > maxTimestampLength) { 
    return { timestamp: timestamp.substring(0x0, maxTimestampLength), message };
  }

  const initialBufferSize = 0x40; 
  const processedMessage = message.trim();
  if (processedMessage.length === 0x0 && timestamp.length > 0x10) { 
     return { timestamp: timestamp, message: "(empty)" };
  }

  return { timestamp: timestamp, message: processedMessage };
}

