function isSmallIntArray(arr) {
  for (const v of arr) {
    if (!Number.isInteger(v) || v < 0 || v > 65535) return false;
  }
  return true;
}

function radixSelect(arr, k) {
  const highCounts = new Uint32Array(256);
  for (const v of arr) highCounts[v >>> 8]++;
  let rank = k;
  let bucket = 0;
  while (rank > highCounts[bucket]) {
    rank -= highCounts[bucket];
    bucket++;
  }
  const lowCounts = new Uint32Array(256);
  for (const v of arr) {
    if ((v >>> 8) === bucket) lowCounts[v & 255]++;
  }
  let low = 0;
  while (rank > lowCounts[low]) {
    rank -= lowCounts[low];
    low++;
  }
  return (bucket << 8) | low;
}

function rangeSelect(arr, k, min, span) {
  const counts = new Uint32Array(span + 1);
  for (const v of arr) counts[v - min]++;
  let rank = k;
  let offset = 0;
  while (rank > counts[offset]) {
    rank -= counts[offset];
    offset++;
  }
  return min + offset;
}

function insertionSort(a, lo, hi) {
  for (let i = lo + 1; i <= hi; i++) {
    const v = a[i];
    let j = i - 1;
    while (j >= lo && a[j] > v) a[j + 1] = a[j--];
    a[j + 1] = v;
  }
}

function partition(a, lo, hi) {
  const mid = (lo + hi) >>> 1;
  if (a[mid] < a[lo]) [a[mid], a[lo]] = [a[lo], a[mid]];
  if (a[hi] < a[lo]) [a[hi], a[lo]] = [a[lo], a[hi]];
  if (a[mid] < a[hi]) [a[mid], a[hi]] = [a[hi], a[mid]];
  const pivot = a[hi];
  let store = lo;
  for (let i = lo; i < hi; i++) {
    if (a[i] < pivot) {
      [a[i], a[store]] = [a[store], a[i]];
      store++;
    }
  }
  [a[store], a[hi]] = [a[hi], a[store]];
  return store;
}

function quickSelect(a, k) {
  let lo = 0;
  let hi = a.length - 1;
  const target = k - 1;
  for (;;) {
    if (hi - lo < 32) {
      insertionSort(a, lo, hi);
      return a[target];
    }
    const p = partition(a, lo, hi);
    if (p === target) return a[p];
    if (target < p) hi = p - 1;
    else lo = p + 1;
  }
}

function findKthSmallest(arr, k) {
  if (isSmallIntArray(arr)) {
    let min = arr[0];
    let max = arr[0];
    for (const v of arr) {
      if (v < min) min = v;
      if (v > max) max = v;
    }
    const span = max - min;
    if (span < 4096) return rangeSelect(arr, k, min, span);
    if (arr.length >= 1024) return radixSelect(arr, k);
  }
  return quickSelect(arr.slice(), k);
}

function formatResult(arr, k) {
  return `findKthSmallest([${arr.join(', ')}], ${k}) => ${findKthSmallest(arr, k)}`;
}

console.log(formatResult([3, 2, 1, 5, 6, 4], 2));
console.log(formatResult([7, 10, 4, 3, 20, 15], 3));

module.exports = { findKthSmallest, formatResult };

