  const rotated = areRotations(s1, s2);
  const offset = rotated && s1.length > 0 ? findRotationOffset(s1 + s1, s2) : -1;
  const detail = offset > 0 ? ' (shift ' + offset + ')' : '';
  return preview(s1) + ' / ' + preview(s2) + ': ' + rotated + detail;
}

