function assertValidPoints(points) {
  if (!Array.isArray(points)) {
    throw new TypeError('points must be an array of numbers');
  }
  if (points.length < 2) {
    throw new RangeError('at least two points are required');
  }
  for (const value of points) {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`invalid coordinate: ${value}`);
    }
  }
}

function insertionSort(values) {
  for (let i = 1; i < values.length; i++) {
    const current = values[i];
    let j = i - 1;
    while (j >= 0 && values[j] > current) {
      values[j + 1] = values[j];
      j--;
    }
    values[j + 1] = current;
  }
  return values;
}

function isRadixSortable(values) {
  return values.every((v) => Number.isInteger(v) && v >= 0 && v <= 65535);
}

function radixSortBytes(values) {
  let source = values.slice();
  let dest = new Array(values.length);
  for (const shift of [0, 8]) {
    const counts = new Array(256).fill(0);
    for (const v of source) {
      counts[(v >> shift) & 255]++;
    }
    let running = 0;
    for (let bucket = 0; bucket < counts.length; bucket++) {
      const size = counts[bucket];
      counts[bucket] = running;
      running += size;
    }
    for (const v of source) {
      dest[counts[(v >> shift) & 255]++] = v;
    }
    const swap = source;
    source = dest;
    dest = swap;
  }
  return source;
}

function sortPoints(points) {
  if (points.length <= 32) {
    return insertionSort(points.slice());
  }
  if (points.length >= 4096 && isRadixSortable(points)) {
    return radixSortBytes(points);
  }
  return points.slice().sort((a, b) => a - b);
}

function closestPairDetails(points) {
  assertValidPoints(points);
  const sorted = sortPoints(points);
  let best = { left: sorted[0], right: sorted[1], distance: Infinity };
  for (let i = 1; i < sorted.length; i++) {
    const distance = sorted[i] - sorted[i - 1];
    if (distance < best.distance) {
      best = { left: sorted[i - 1], right: sorted[i], distance };
    }
  }
  return best;
}

function closestPair1D(points) {
  return closestPairDetails(points).distance;
}

function formatReport(label, points) {
  const { left, right, distance } = closestPairDetails(points);
  const pair = `${left} .. ${right}`;
  const column = pair.padEnd(16);
  return `${label.padEnd(16)}${column}distance=${distance}`;
}

const args = process.argv.slice(2).map(Number);
if (args.length >= 2) {
  console.log(formatReport('input', args));
} else {
  console.log(formatReport('example 1', [1, 5, 2, 8]));
  console.log(formatReport('example 2', [10, 20, 15]));
}

module.exports = { closestPair1D, closestPairDetails, formatReport };

