'use strict';

const DAY_MASK = 255;
const MONTH_MULT = 256;
const YEAR_MULT = MONTH_MULT * MONTH_MULT;
const CACHE_LIMIT = 4096;
const keyCache = new Map();

function isLeapYear(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function daysInMonth(year, month) {
  if (month === 2) return isLeapYear(year) ? 29 : 28;
  return month === 4 || month === 6 || month === 9 || month === 11 ? 30 : 31;
}

function parseDateKey(text) {
  if (typeof text !== 'string') throw new TypeError('date must be a string');
  const cached = keyCache.get(text);
  if (cached !== undefined) return cached;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) throw new RangeError('malformed date: ' + text);
  const year = Number(text.slice(0, 4));
  const month = Number(text.slice(5, 7));
  const day = Number(text.slice(8, 10));
  if (month < 1 || month > 12) throw new RangeError('month out of range: ' + text);
  if (day < 1 || day > daysInMonth(year, month)) throw new RangeError('day out of range: ' + text);
  const key = year * YEAR_MULT + month * MONTH_MULT + day;
  if (keyCache.size >= CACHE_LIMIT) keyCache.clear();
  keyCache.set(text, key);
  return key;
}

function formatDateKey(key) {
  const year = Math.floor(key / YEAR_MULT);
  const month = Math.floor(key / MONTH_MULT) & DAY_MASK;
  const day = key & DAY_MASK;
  return [
    String(year).padStart(4, '0'),
    String(month).padStart(2, '0'),
    String(day).padStart(2, '0'),
  ].join('-');
}

function filterByDateRange(items, startDate, endDate) {
  if (!Array.isArray(items)) throw new TypeError('items must be an array');
  const start = parseDateKey(startDate);
  const end = parseDateKey(endDate);
  if (start > end) throw new RangeError('startDate must not be after endDate');
  return items.filter((item) => {
    if (!item || typeof item !== 'object') throw new TypeError('each item must be an object');
    const key = parseDateKey(item.date);
    return key >= start && key <= end;
  });
}

function formatReport(matches, startDate, endDate) {
  const lines = ['range ' + startDate + ' .. ' + endDate, '-'.repeat(64)];
  for (const item of matches) {
    lines.push(formatDateKey(parseDateKey(item.date)).padStart(16));
  }
  lines.push('matched ' + matches.length + ' item(s)');
  return lines.join('\n');
}

function main() {
  const items = [
    { date: '2023-01-01' },
    { date: '2023-01-10' },
    { date: '2023-02-28' },
    { date: '2024-02-29' },
  ];
  const startDate = '2023-01-05';
  const endDate = '2024-01-15';
  console.log(formatReport(filterByDateRange(items, startDate, endDate), startDate, endDate));
}

main();

module.exports = { filterByDateRange, parseDateKey, formatDateKey, formatReport };

