const MAX_URL_LENGTH = 4096;
const MAX_PARAMS = 256;
const MAX_KEY_LENGTH = 255;
const HEX_RADIX = 16;
const SPACE_CODE = 32;
const ASCII_LIMIT = 128;
const CONTINUATION_SHIFT = 64;
const BMP_LIMIT = 65535;
const SURROGATE_BLOCK = 1024;
const CONTINUATION_LIMIT = 192;
const THREE_BYTE_LEAD = 224;
const FOUR_BYTE_LEAD = 240;
const HIGH_SURROGATE_BASE = 55296;
const LOW_SURROGATE_BASE = 56320;
const REPLACEMENT = '\uFFFD';

function readPercentByte(source, index) {
  if (source[index] !== '%') return -1;
  const hex = source.slice(index + 1, index + 3);
  if (!/^[0-9a-fA-F]{2}$/.test(hex)) return -1;
  return parseInt(hex, HEX_RADIX);
}

function appendCodePoint(out, cp) {
  if (cp > BMP_LIMIT) {
    const rest = cp - BMP_LIMIT - 1;
    const high = HIGH_SURROGATE_BASE + Math.floor(rest / SURROGATE_BLOCK);
    const low = LOW_SURROGATE_BASE + (rest % SURROGATE_BLOCK);
    out.push(String.fromCharCode(high, low));
  } else {
    out.push(String.fromCharCode(cp));
  }
}

function decodeComponent(raw) {
  const out = [];
  let i = 0;
  while (i < raw.length) {
    const ch = raw[i];
    if (ch === '+') {
      out.push(String.fromCharCode(SPACE_CODE));
      i += 1;
      continue;
    }
    const lead = readPercentByte(raw, i);
    if (lead < 0) {
      out.push(ch);
      i += 1;
      continue;
    }
    i += 3;
    if (lead < ASCII_LIMIT) {
      out.push(String.fromCharCode(lead));
      continue;
    }
    let pending;
    let cp;
    if (lead >= FOUR_BYTE_LEAD) {
      pending = 3;
      cp = lead - FOUR_BYTE_LEAD;
    } else if (lead >= THREE_BYTE_LEAD) {
      pending = 2;
      cp = lead - THREE_BYTE_LEAD;
    } else if (lead >= CONTINUATION_LIMIT) {
      pending = 1;
      cp = lead - CONTINUATION_LIMIT;
    } else {
      out.push(REPLACEMENT);
      continue;
    }
    while (pending > 0) {
      const cont = readPercentByte(raw, i);
      if (cont < ASCII_LIMIT || cont >= CONTINUATION_LIMIT) {
        cp = -1;
        break;
      }
      cp = cp * CONTINUATION_SHIFT + (cont - ASCII_LIMIT);
      i += 3;
      pending -= 1;
