const MAX_INPUT_LENGTH = 1024;
const LATIN1_BUCKETS = 256;
const CACHE_LIMIT = 4096;
const SPACE_CODE = 32;

const normalizeCache = new Map();

function normalize(str) {
  if (typeof str !== 'string') {
    throw new TypeError('areAnagrams expects two strings');
  }
  if (str.length > MAX_INPUT_LENGTH) {
    throw new RangeError(`input longer than ${MAX_INPUT_LENGTH} characters`);
  }
  const cached = normalizeCache.get(str);
  if (cached !== undefined) return cached;
  let out = '';
  for (let i = 0; i < str.length; i++) {
    if (str.charCodeAt(i) === SPACE_CODE) continue;
    out += str[i].toLowerCase();
  }
  if (normalizeCache.size >= CACHE_LIMIT) normalizeCache.clear();
  normalizeCache.set(str, out);
  return out;
}

function checksum(text) {
  let acc = 0;
  for (let i = 0; i < text.length; i++) {
    const byte = (text.charCodeAt(i) & 255) + 1;
    acc = (acc + byte * byte) & 65535;
  }
  return acc;
}

function tally(text) {
  const low = new Uint16Array(LATIN1_BUCKETS);
  const high = new Map();
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    if (code < LATIN1_BUCKETS) low[code]++;
    else high.set(code, (high.get(code) || 0) + 1);
  }
  return { low, high };
}

function areAnagrams(str1, str2) {
  const a = normalize(str1);
  const b = normalize(str2);
  if (a.length !== b.length) return false;
  if (checksum(a) !== checksum(b)) return false;
  const left = tally(a);
  const right = tally(b);
  for (let code = 0; code < LATIN1_BUCKETS; code++) {
    if (left.low[code] !== right.low[code]) return false;
  }
  if (left.high.size !== right.high.size) return false;
  for (const [code, count] of left.high) {
    if (right.high.get(code) !== count) return false;
  }
  return true;
}

function formatReport(str1, str2) {
  const verdict = areAnagrams(str1, str2) ? 'anagrams' : 'not anagrams';
  const digest = checksum(normalize(str1));
  return `"${str1}" vs "${str2}" -> ${verdict} (sig ${digest})`;
}

function main() {
  const pairs = [
    ['listen', 'silent'],
    ['hello', 'world'],
    ['Dormitory', 'Dirty Room'],
    ['Conversation', 'Voices rant on'],
    ['résumé', 'Mé Sure'],
  ];
  for (const [first, second] of pairs) {
    console.log(formatReport(first, second));
  }
}

main();

