'use strict';

const MAX_BUCKETS = 4096;
const SMALL_INT_LIMIT = 256;
const MAX_TEXT = 1024;
const FNV_OFFSET = 2166136261;
const FNV_PRIME = 16777619;

function keyOf(value) {
  if (typeof value === 'string') return 's:' + value;
  if (typeof value === 'number') return 'n:' + (value === 0 ? '0' : String(value));
  if (value === null) return 'null:';
  return typeof value + ':' + String(value);
}

function hashString(s) {
  let h = FNV_OFFSET;
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i) & 65535;
    if (code < 128) {
      h = Math.imul(h ^ code, FNV_PRIME);
    } else {
      h = Math.imul(h ^ (code & 255), FNV_PRIME);
      h = Math.imul(h ^ (code >>> 8), FNV_PRIME);
    }
  }
  return h >>> 0;
}

function bucketCount(size) {
  let n = 64;
  while (n < size && n < MAX_BUCKETS) n *= 2;
  return n;
}

function addKey(index, key) {
  const slot = hashString(key) & index.mask;
  const bucket = index.buckets[slot] || (index.buckets[slot] = []);
  if (bucket.indexOf(key) !== -1) return false;
  bucket.push(key);
  return true;
}

function hasKey(index, key) {
  const bucket = index.buckets[hashString(key) & index.mask];
  return bucket !== undefined && bucket.indexOf(key) !== -1;
}

function createIndex(values) {
  const count = bucketCount(values.length);
  const index = { buckets: new Array(count), mask: count - 1 };
  for (const v of values) addKey(index, keyOf(v));
  return index;
}

function isByteArray(arr) {
  return arr.every((v) => Number.isInteger(v) && v >= 0 && v < SMALL_INT_LIMIT);
}

function byteIntersection(source, scanned) {
  const seen = new Int32Array(SMALL_INT_LIMIT / 32);
  const taken = new Int32Array(seen.length);
  for (const v of source) seen[v >>> 5] |= 1 << (v & 31);
  const out = [];
  for (const v of scanned) {
    const word = v >>> 5;
    const bit = 1 << (v & 31);
    if ((seen[word] & bit) !== 0 && (taken[word] & bit) === 0) {
      taken[word] |= bit;
      out.push(v);
    }
  }
  return out;
}

function findCommonElements(arr1, arr2) {
  if (!Array.isArray(arr1) || !Array.isArray(arr2)) {
    throw new TypeError('findCommonElements expects two arrays');
  }
  if (arr1.length === 0 || arr2.length === 0) return [];
  const small = arr1.length <= arr2.length ? arr1 : arr2;
  const large = small === arr1 ? arr2 : arr1;
  if (isByteArray(small) && isByteArray(large)) return byteIntersection(large, small);
  const seen = createIndex(small);
  const emitted = createIndex([]);
  const out = [];
  for (const v of large) {
    const key = keyOf(v);
    if (hasKey(seen, key) && addKey(emitted, key)) out.push(v);
  }
  return out;
}

function formatResult(values) {
  const parts = values.map((v) => (typeof v === 'string' ? JSON.stringify(v) : String(v)));
  const text = '[' + parts.join(', ') + ']';
  if (text.length > MAX_TEXT) return text.slice(0, MAX_TEXT) + '...';
  return text;
}

const evens = [];
for (let i = 0; i < 1024; i += 2) evens.push(i);
const bytes = [];
for (let i = 0; i <= 255; i++) bytes.push(i);

console.log(formatResult(findCommonElements([1, 2, 3], [2, 3, 4])));
console.log(formatResult(findCommonElements(['a', 'b'], ['c', 'd'])));
console.log(formatResult(findCommonElements(['x', 'y', 'z'], ['z', 'y', 'q'])));
console.log(formatResult(findCommonElements(evens, bytes)));

