'use strict';

// Capitalization utilities: words are the space-separated runs of a string.

const CONTROL_LIMIT = 32;
const MAX_INPUT_LENGTH = 4096;
const CACHE_LIMIT = 1024;
const HEX = 16;
const ASCII_MAX = 128;
const LATIN1_MAX = 255;
const BMP_MAX = 65535;
const HISTOGRAM_SIZE = 256;

function assertPlainText(str) {
  if (typeof str !== 'string') {
    throw new TypeError('capitalizeWords expects a string');
  }
  if (str.length > MAX_INPUT_LENGTH) {
    throw new RangeError('input longer than ' + MAX_INPUT_LENGTH + ' UTF-16 units');
  }
  for (const ch of str) {
    const code = ch.codePointAt();
    if (code < CONTROL_LIMIT) {
      throw new RangeError('control character 0x' + code.toString(HEX) + ' in input');
    }
  }
}

const wordCache = new Map();

function capitalizeWord(word) {
  if (wordCache.has(word)) return wordCache.get(word);
  const out = word.replace(/^\p{Ll}/u, ch => ch.toUpperCase());
  if (wordCache.size >= CACHE_LIMIT) wordCache.clear();
  wordCache.set(word, out);
  return out;
}

function capitalizeWords(str) {
  assertPlainText(str);
  return str.split(' ').map(capitalizeWord).join(' ');
}

function describeCharset(str) {
  let max = Number.NEGATIVE_INFINITY;
  for (const ch of str) {
    const cp = ch.codePointAt();
    if (cp > max) max = cp;
  }
  if (max < ASCII_MAX) return 'ascii';
  if (max <= LATIN1_MAX) return 'latin1';
  if (max <= BMP_MAX) return 'bmp';
  return 'astral';
}

function topCharacter(str) {
  const counts = new Uint32Array(HISTOGRAM_SIZE);
  for (const ch of str) {
    const code = ch.codePointAt();
    if (code > CONTROL_LIMIT && code <= LATIN1_MAX) counts[code]++;
  }
  const best = counts.indexOf(Math.max(...counts));
  return counts[best] ? String.fromCharCode(best) + ' x' + counts[best] : 'none';
}

function formatReport(input, output) {
  return [
    'in  : ' + JSON.stringify(input),
    'out : ' + JSON.stringify(output),
    'meta: ' + describeCharset(input) + ', ' + Buffer.byteLength(input, 'utf8') +
      ' utf8 bytes, top character ' + topCharacter(input),
  ].join('\n');
}

function main() {
  const samples = ['hello world', 'javascript is fun', 'thé naïve café crew'];
  for (const sample of samples) {
    console.log(formatReport(sample, capitalizeWords(sample)));
  }
}

main();

module.exports = { capitalizeWords, capitalizeWord, describeCharset, topCharacter, formatReport };

