const MAX_ITEMS = 65535;
const INSERTION_THRESHOLD = 32;
const MAX_KEY_LENGTH = 255;
const ASCII_LIMIT = 128;
const INDEX_WIDTH = 16;
const VALUE_WIDTH = 64;
const TABLE_LIMIT = 1024;

function normalizeKey(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (value === null || value === undefined) return '';
  const text = String(value);
  return text.length > MAX_KEY_LENGTH ? text.slice(0, MAX_KEY_LENGTH) : text;
}

function compareStrings(a, b) {
  const shared = Math.min(a.length, b.length);
  for (let i = 0; i < shared; i++) {
    const ca = a.charCodeAt(i);
    const cb = b.charCodeAt(i);
    if (ca === cb) continue;
    if (Math.max(ca, cb) < ASCII_LIMIT) return ca - cb;
    return a.slice(i).localeCompare(b.slice(i));
  }
  return a.length - b.length;
}

function compareKeys(a, b) {
  if (typeof a === 'number' && typeof b === 'number') return a - b;
  if (typeof a === 'number') return -1;
  if (typeof b === 'number') return 1;
  return compareStrings(a, b);
}

function insertionSort(entries, from, to) {
  for (let i = from + 1; i < to; i++) {
    const current = entries[i];
    let j = i - 1;
    while (j >= from && compareKeys(entries[j].key, current.key) > 0) {
      entries[j + 1] = entries[j];
      j--;
    }
    entries[j + 1] = current;
  }
}

function mergeSort(entries, from, to, buffer) {
  if (to - from <= INSERTION_THRESHOLD) return insertionSort(entries, from, to);
  const mid = (from + to) >> 1;
  mergeSort(entries, from, mid, buffer);
  mergeSort(entries, mid, to, buffer);
  let left = from;
  let right = mid;
  for (let out = from; out < to; out++) {
    if (left < mid && (right >= to || compareKeys(entries[left].key, entries[right].key) <= 0)) {
      buffer[out] = entries[left++];
    } else {
      buffer[out] = entries[right++];
    }
  }
  for (let i = from; i < to; i++) entries[i] = buffer[i];
}

function sortObjectsByProperty(arr, prop) {
  if (!Array.isArray(arr)) throw new TypeError('arr must be an array');
  if (typeof prop !== 'string' || prop.length === 0) throw new TypeError('prop must be a non-empty string');
  if (arr.length > MAX_ITEMS) throw new RangeError(`arr may hold at most ${MAX_ITEMS} objects`);
  const entries = arr.map((item) => ({ item, key: normalizeKey(item == null ? undefined : item[prop]) }));
  mergeSort(entries, 0, entries.length, new Array(entries.length));
  return entries.map((entry) => entry.item);
}

function cell(text, width) {
  const s = String(text);
  return (s.length > width ? s.slice(0, width - 1) + '\u2026' : s).padEnd(width);
}

function formatTable(arr, prop) {
  const sorted = sortObjectsByProperty(arr, prop).slice(0, TABLE_LIMIT);
  const header = cell('#', INDEX_WIDTH) + cell(prop, VALUE_WIDTH);
  const lines = [header, '-'.repeat(header.length)];
  sorted.forEach((item, index) => {
    const value = cell(normalizeKey(item[prop]), VALUE_WIDTH);
    lines.push(cell(index + 1, INDEX_WIDTH) + value);
  });
  return lines.join('\n');
}

