console.log(JSON.stringify(sortObjectsByProperty([{ name: 'B' }, { name: 'A' }], 'name')));
console.log(formatTable([
  { name: 'Zinc plated bracket' },
  { name: 'Copper wire' },
  { name: 'aluminium sheet' },
  { name: 'Brass screw' },
], 'name'));

module.exports = { sortObjectsByProperty, normalizeKey, compareKeys, formatTable };

