'use strict';

const BYTE_MASK = 255;
const BYTE_MODULUS = 256;
const BYTE_SIGN_BIT = 128;
const WORD_MASK = 65535;
const WORD_BITS = 16;
const HEX_RADIX = 16;
const MAX_BITS = 32;
const REPORT_WIDTH = 64;

function cleanBits(binaryStr) {
  if (typeof binaryStr !== 'string') {
    throw new TypeError('binaryStr must be a string');
  }
  const bits = binaryStr.trim().replace(/[\s_]/g, '');
  if (!/^[01]+$/.test(bits)) {
    throw new SyntaxError(`not a binary string: "${binaryStr}"`);
  }
  if (bits.length > MAX_BITS) {
    throw new RangeError(`at most ${MAX_BITS} bits are supported`);
  }
  return bits;
}

function fitToWidth(bits, width) {
  if (bits.length > width) {
    throw new RangeError(`${bits.length} bits do not fit in ${width} bits`);
  }
  return bits.padStart(width, '0');
}

function toUnsigned(bits) {
  let value = 0;
  for (const ch of bits) {
    value = value * 2 + (ch === '1' ? 1 : 0);
  }
  return value;
}

function signedBinaryToDecimal(binaryStr) {
  const value = toUnsigned(fitToWidth(cleanBits(binaryStr), 8)) & BYTE_MASK;
  return (value & BYTE_SIGN_BIT) !== 0 ? value - BYTE_MODULUS : value;
}

function signedWordToDecimal(binaryStr) {
  const value = toUnsigned(fitToWidth(cleanBits(binaryStr), WORD_BITS)) & WORD_MASK;
  const modulus = WORD_MASK + 1;
  return value >= modulus / 2 ? value - modulus : value;
}

function decimalToSignedBinary(n) {
  if (!Number.isInteger(n) || n < -BYTE_SIGN_BIT || n > BYTE_SIGN_BIT - 1) {
    throw new RangeError(`${n} is not representable as a signed byte`);
  }
  const value = ((n % BYTE_MODULUS) + BYTE_MODULUS) & BYTE_MASK;
  return value.toString(2).padStart(8, '0');
}

function toHexByte(binaryStr) {
  const value = toUnsigned(fitToWidth(cleanBits(binaryStr), 8)) & BYTE_MASK;
  return '0x' + value.toString(HEX_RADIX).padStart(2, '0');
}

function bitWeights(binaryStr) {
  const bits = fitToWidth(cleanBits(binaryStr), 8);
  const terms = [];
  let weight = BYTE_SIGN_BIT;
  for (const ch of bits) {
    if (ch === '1') {
      terms.push(weight === BYTE_SIGN_BIT ? `-${weight}` : String(weight));
    }
    weight /= 2;
  }
  return terms.length > 0 ? terms.join(' + ') : '0';
}

function describeByte(binaryStr) {
  const decimal = signedBinaryToDecimal(binaryStr);
  const canonical = decimalToSignedBinary(decimal);
  return `${canonical}  ${toHexByte(canonical)}  ${String(decimal).padStart(4)}  = ${bitWeights(canonical)}`;
}

function main() {
  console.log('bits      hex   dec   weights');
  console.log('-'.repeat(REPORT_WIDTH));
  for (const sample of ['00001010', '11111110', '0111_1111', '10000000', '11']) {
    console.log(describeByte(sample));
  }
  console.log('-'.repeat(REPORT_WIDTH));
  console.log('16-bit 1111111111111110 ->', signedWordToDecimal('1111111111111110'));
  console.log('16-bit 0000010000000000 ->', signedWordToDecimal('0000010000000000'));
}

main();

module.exports = {
  signedBinaryToDecimal,
  signedWordToDecimal,
  decimalToSignedBinary,
  toHexByte,
  bitWeights,
  describeByte
};

