'use strict';

const POOL_BYTES = 4096;
const BYTE_MASK = 255;
const BYTE_SCALE = 256;
const WORD_MAX = 65535;
const BAR_WIDTH = 32;
const COLUMN_WIDTH = 16;
const RULE_WIDTH = 64;
const TRIALS = 1024;

// 32-bit xorshift generator, seeded from the clock and Math.random.
let state = ((Date.now() ^ (Math.random() * 4294967296)) >>> 0) || 1;

function xorshift32() {
  state ^= state << 13;
  state ^= state >>> 17;
  state ^= state << 5;
  return state >>> 0;
}

// Random bytes are drawn from a pre-generated pool so long runs stay cheap.
const pool = new Array(POOL_BYTES);
let cursor = POOL_BYTES;

function fillPool() {
  for (let i = 0; i < POOL_BYTES; i++) {
    pool[i] = xorshift32() & BYTE_MASK;
  }
  cursor = 0;
}

// Two pool bytes make one uniform word in [0, WORD_MAX].
function nextWord() {
  if (cursor + 2 > POOL_BYTES) {
    fillPool();
  }
  const high = pool[cursor++];
  const low = pool[cursor++];
  return high * BYTE_SCALE + low;
}

function weightedCoinFlip(headsProbability) {
  if (typeof headsProbability !== 'number' || Number.isNaN(headsProbability)) {
    throw new TypeError('headsProbability must be a number');
  }
  if (headsProbability < 0 || headsProbability > 1) {
    throw new RangeError('headsProbability must be between 0 and 1');
  }
  if (headsProbability === 0) return 'tails';
  if (headsProbability === 1) return 'heads';
  const threshold = Math.round(headsProbability * WORD_MAX);
  return nextWord() <= threshold ? 'heads' : 'tails';
}

function flipSeries(headsProbability, trials) {
  const counts = { heads: 0, tails: 0 };
  for (let i = 0; i < trials; i++) {
    counts[weightedCoinFlip(headsProbability)]++;
  }
  return counts;
}

function bar(fraction) {
  const filled = Math.round(fraction * BAR_WIDTH);
  return '#'.repeat(filled) + '.'.repeat(BAR_WIDTH - filled);
}

function formatRow(headsProbability, counts, trials) {
  const observed = counts.heads / trials;
  const label = `p=${headsProbability.toFixed(2)}`.padEnd(COLUMN_WIDTH);
  const tally = `${counts.heads}H/${counts.tails}T`.padEnd(COLUMN_WIDTH);
  return `${label}${tally}${bar(observed)}  ${(observed * 100).toFixed(1)}%`;
}

function main() {
  console.log(`weighted coin flip: ${TRIALS} trials per probability`);
  console.log('-'.repeat(RULE_WIDTH));
  for (const p of [0, 0.2, 0.5, 0.8, 1]) {
    console.log(formatRow(p, flipSeries(p, TRIALS), TRIALS));
  }
  console.log('-'.repeat(RULE_WIDTH));
  console.log(`single flip at 0.8 -> ${weightedCoinFlip(0.8)}`);
  console.log(`single flip at 0.2 -> ${weightedCoinFlip(0.2)}`);
}

main();

module.exports = { weightedCoinFlip, flipSeries };

