const MAX_TASK_LENGTH = 128;
const MAX_LIST_SIZE = 1024;
const PREVIEW_WIDTH = 64;
const LABEL_WIDTH = 32;
const MAX_REPORT_LENGTH = 4096;

function fingerprint(text) {
  let h = 0;
  for (let i = 0; i < text.length; i += 1) {
    const byte = text.charCodeAt(i) & 255;
    h = h * 256 + byte;
    h &= 65535;
  }
  return String(h).padStart(5, '0');
}

function validateTask(task) {
  if (typeof task !== 'string') {
    throw new TypeError('task must be a string');
  }
  if (task.length === 0) {
    throw new RangeError('task must not be empty');
  }
  if (task.length > MAX_TASK_LENGTH) {
    throw new RangeError('task must not exceed ' + MAX_TASK_LENGTH + ' characters');
  }
}

function removeTask(todoList, taskToRemove) {
  if (!Array.isArray(todoList)) {
    throw new TypeError('todoList must be an array');
  }
  if (todoList.length > MAX_LIST_SIZE) {
    throw new RangeError('todoList must not hold more than ' + MAX_LIST_SIZE + ' tasks');
  }
  validateTask(taskToRemove);
  const index = todoList.indexOf(taskToRemove);
  if (index === -1) {
    return todoList;
  }
  return todoList.slice(0, index).concat(todoList.slice(index + 1));
}

function preview(text) {
  if (text.length <= PREVIEW_WIDTH) {
    return text;
  }
  return text.slice(0, PREVIEW_WIDTH) + '...';
}

function formatRow(label, value) {
  return label.padEnd(LABEL_WIDTH, ' ') + '| ' + value;
}

function buildReport(before, after, taskToRemove) {
  const lines = [
    formatRow('requested removal', preview(taskToRemove)),
