const DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

const MASK_LIMIT = 128;
const SATURDAY_BIT = 64;
const WEEKEND_MASK = SATURDAY_BIT | 1;
const MASK_BYTE = 255;
const HOUR_SCALE = 256;
const PACKED_LIMIT = 65535;

function getCurrentDayOfWeek() {
  return DAY_NAMES[new Date().getDay()];
}

function dayFlag(name) {
  const index = DAY_NAMES.indexOf(name);
  if (index < 0) {
    throw new Error('unknown day name: ' + name);
  }
  return 1 << index;
}

function maskFromNames(names) {
  return names.reduce(function (mask, name) {
    return mask | dayFlag(name);
  }, 0);
}

function namesFromMask(mask) {
  if (!Number.isInteger(mask) || mask < 0 || mask >= MASK_LIMIT) {
    throw new Error('day mask must be an integer below ' + MASK_LIMIT + ', got ' + mask);
  }
  return DAY_NAMES.filter(function (name, index) {
    return (mask >> index) & 1;
  });
}

function packSchedule(mask, hour) {
  namesFromMask(mask);
  if (!Number.isInteger(hour) || hour < 0 || hour > 23) {
    throw new Error('hour must be an integer in 0..23, got ' + hour);
  }
  return hour * HOUR_SCALE + mask;
}

function unpackSchedule(packed) {
  if (!Number.isInteger(packed) || packed < 0 || packed > PACKED_LIMIT) {
    throw new Error('packed schedule must fit in 16 bits, got ' + packed);
  }
  const mask = packed & MASK_BYTE;
  return { mask: mask, hour: Math.floor(packed / HOUR_SCALE), days: namesFromMask(mask) };
}

function describeSchedule(packed) {
  const schedule = unpackSchedule(packed);
  const time = String(schedule.hour).padStart(2, '0') + ':00';
  return schedule.days.join(', ') + ' at ' + time;
}

function main() {
  const today = getCurrentDayOfWeek();
  const flag = dayFlag(today);
  console.log('Today is ' + today);
  console.log(flag & WEEKEND_MASK ? 'It is the weekend.' : 'It is a working day.');

  const workweek = maskFromNames(['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday']);
  const remaining = workweek & ~((flag << 1) - 1);
  console.log('Working days still ahead: ' + (remaining ? namesFromMask(remaining).join(', ') : 'none'));

  const packed = packSchedule(maskFromNames(['Monday', 'Wednesday', 'Friday']), 9);
  console.log('Standup schedule: ' + describeSchedule(packed));
}

main();

