const MAX_ADDRESS_LENGTH = 255;
const MAX_LOCAL_LENGTH = 64;
const MIN_PRINTABLE_CODE = 32;
const ASCII_CODE_LIMIT = 128;
const DISPLAY_WIDTH = 32;

function hasOnlyPrintableAscii(text) {
  let index = text.length;
  while (index--) {
    const code = text.charCodeAt(index);
    if (code < MIN_PRINTABLE_CODE || code >= ASCII_CODE_LIMIT) {
      return false;
    }
  }
  return true;
}

function splitAddress(email) {
  const [local, ...rest] = email.split('@');
  const domain = rest.join('@');
  if (!rest.length || domain.includes('@') || !domain.includes('.')) {
    return null;
  }
  return { local, domain };
}

function lengthProblem(email, parts) {
  if (email.length > MAX_ADDRESS_LENGTH) {
    return 'address is too long';
  }
  if (!parts.local) {
    return 'local part is empty';
  }
  if (parts.local.length > MAX_LOCAL_LENGTH) {
    return 'local part is too long';
  }
  return null;
}

function describeProblem(email) {
  if (typeof email !== 'string') {
    return 'input is not a string';
  }
  const trimmed = email.trim();
  if (!trimmed) {
    return 'address is empty';
  }
  if (!hasOnlyPrintableAscii(trimmed)) {
    return 'contains control or non-ASCII characters';
  }
  const parts = splitAddress(trimmed);
  if (parts === null) {
    return "needs a single '@' followed later by a '.'";
  }
  if (parts.domain.startsWith('.') || parts.domain.endsWith('.')) {
    return 'domain cannot start or end with a dot';
  }
  if (parts.domain.includes('..')) {
    return 'domain cannot contain an empty label';
  }
  return lengthProblem(trimmed, parts);
}

function isValidEmail(email) {
  return describeProblem(email) === null;
}

function formatRow(email, problem) {
  const shown = typeof email === 'string' ? email : String(email);
  const clipped = shown.length > DISPLAY_WIDTH ? `...${shown.slice(-DISPLAY_WIDTH)}` : shown;
  const verdict = problem === null ? 'valid' : `invalid: ${problem}`;
  return `${clipped.padEnd(DISPLAY_WIDTH)} | ${verdict}`;
}

function main() {
  const samples = [
    'test@example.com',
    'invalid-email',
    'user.name@mail.co.uk',
    'no.dot@localhost',
    '@example.com',
    'double@@example.com',
    'dots@example..com',
    'bad\u0001char@example.com',
    `${'a'.repeat(MAX_LOCAL_LENGTH)}@example.com`,
    `${'b'.repeat(MAX_ADDRESS_LENGTH - MAX_LOCAL_LENGTH)}@example.com`,
    `${'c'.repeat(MAX_ADDRESS_LENGTH)}@example.com`,
  ];
  for (const sample of samples) {
    console.log(formatRow(sample, describeProblem(sample)));
  }
}

main();

module.exports = { isValidEmail, describeProblem };

